lemma heightRank_pred_finite {H : ℂ → ℝ} {S : Set ℂ} {z : ℂ}
    (hfin : (S ∩ {w | H z ≤ H w}).Finite) :
    @Set.Finite ℂ (S ∩ @Iio ℂ (heightOrder H).toPreorder z)

lemma rankPartner_eq {H : ℂ → ℝ} {A B : Set ℂ} {z w : ℂ}
    (hri : InjOn (heightRank H B) B) (hw : w ∈ B)
    (hr : heightRank H B w = heightRank H A z) : rankPartner H A B z = w

lemma rankPartner_injOn {H : ℂ → ℝ} {A B : Set ℂ}
    (he : ∀ z ∈ A, ∃ w ∈ B, heightRank H B w = heightRank H A z)
    (hri : InjOn (heightRank H A) A) : InjOn (rankPartner H A B) A

lemma jacobianRegion_regular (g : DiskClass) (k σ : ℝ) {z : ℂ}
    (hz : z ∈ jacobianRegion g k σ) :
    LinearMap.det (fderiv ℝ (criticalMap (classFun g) k) z).toLinearMap ≠ 0

lemma measurableSet_halfPlane_pred (P : ℂ → Prop)
    (hP : MeasurableSet {z : halfPlane | P z}) :
    MeasurableSet {z : ℂ | z ∈ halfPlane ∧ P z}

lemma holomorphic_sq_submean_center {f : ℂ → ℂ} {z : ℂ} {R r : ℝ}
    (hf : DifferentiableOn ℂ f (Metric.ball z R)) (hr : 0 < r) (hrR : r < R) :
    Real.pi*r^2*‖f z‖^2 ≤ ∫ w in Metric.closedBall z r, ‖f w‖^2

lemma laplacian_holomorphic_comp {ψ : ℂ → ℝ} {F : ℂ → ℂ} {z : ℂ}
    (hψ : ContDiffAt ℝ 2 ψ (F z)) (hF : AnalyticAt ℂ F z) :
    Laplacian.laplacian (ψ ∘ F) z = ‖deriv F z‖^2*Laplacian.laplacian ψ (F z)

lemma traceFlux_contDiffAt {g : ℝ × ℝ → ℝ} {p : ℝ × ℝ}
    (hg : ContDiffAt ℝ 2 g p) (ε : ℝ) :
    ContDiffAt ℝ 1 (traceFluxX g ε) p ∧ ContDiffAt ℝ 1 (traceFluxY g ε) p

lemma ae_regular_values {f : ℂ → ℂ} {s : Set ℂ}
    (hf : ∀ z ∈ s, DifferentiableAt ℝ f z) :
    ∀ᵐ ξ ∂volume, ∀ z ∈ s, f z = ξ → LinearMap.det (fderiv ℝ f z).toLinearMap ≠ 0

lemma displacementWindow_mono {N M : ℝ} (hNM : N ≤ M) {z w : ℂ}
    (hz : z ∈ halfPlane) (hw : w ∈ halfPlane) (h : displacementWindow N z w) :
    displacementWindow M z w

lemma pair_mem_enlargedBox {N R Y : ℝ} (hN : 1 ≤ N) {z w : ℂ}
    (hz : z ∈ transportBox R 1 Y) (hw : displacementWindow N z w) :
    w ∈ transportBox (R+N*Y) (1/N) (N*Y)

lemma dyadic_growth_compare {a δ : ℝ} (ha : 0 ≤ a) (hδ : 0 < δ) {n : ℕ}
    (hn : δ ≤ 2*(1/2:ℝ)^n) :
    ((2:ℝ)^a)^n ≤ (2:ℝ)^a * δ^(-a)

lemma bijOn_inverse_univalent {U V : Set ℂ} (hU : IsOpen U) {φ : ℂ → ℂ}
    (hφ : DifferentiableOn ℂ φ U) (hb : BijOn φ U V) :
    UnivalentOn (Function.invFunOn φ U) V

lemma koebe_negative_endpoint_lower {w : ℂ}
    (hz : -1 + w ∈ disk) (hw : ‖w‖ < 1 / 2) :
    ‖w‖ ^ (-2 : ℝ) ≤ ‖deriv koebeMap (-1 + w)‖ ^ (-2 : ℝ)

lemma koebe_positive_endpoint_lower {w : ℂ}
    (hz : 1 - w ∈ disk) (h0 : 0 < ‖w‖) (hw : ‖w‖ < 1 / 2) :
    ‖w‖ ^ (-2 : ℝ) ≤ ‖deriv koebeMap (1 - w)‖ ^ (2 / 3 : ℝ)

lemma not_integrable_of_areaMoment_top {f : ℂ → ℂ} {U : Set ℂ} {t : ℝ}
    (h : areaMoment f U t = ⊤) :
    ¬ IntegrableOn (fun z => ‖deriv f z‖ ^ t) U volume

lemma left_cone_mem_disk {w : ℂ}
    (h0 : 0 < ‖w‖) (hsmall : ‖w‖ < 1 / 2)
    (hcone : ‖w‖ / 2 ≤ w.re) : -1 + w ∈ disk

lemma right_cone_mem_disk {w : ℂ}
    (h0 : 0 < ‖w‖) (hsmall : ‖w‖ < 1 / 2)
    (hcone : ‖w‖ / 2 ≤ w.re) : 1 - w ∈ disk

lemma sector_cos_lower {θ : ℝ}
    (hθ : θ ∈ Set.Ioo (-(Real.pi / 3)) (Real.pi / 3)) :
    (1 : ℝ) / 2 ≤ Real.cos θ
